#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(5,23,21))*.5+.5)
float SampleFuzz ( vec2 uv, float rootToTip )
{

    uv *= iChannelResolution[0].xy;
    uv -= smoothstep(0.,1.,fract(uv))-fract(uv);
    uv /= iChannelResolution[0].xy;

    float threshold = mix(.5,.8,pow(rootToTip,1.5)); // shape along the length
    float softness = .3;
    vec4 tap = smoothstep(threshold,threshold+softness,texture(iChannel0,uv));
    return max(tap.a,tap.g);//,tap.b),tap.r);
}

void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);
    vec3 n1,p,q,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1)); 

      vec2 uv = (C-iResolution.xy*.5)/iResolution.y;

    uv.y*=3.;
    uv = uv+uv.yx*vec2(1,-1);

    vec3 col = vec3(0);
    for ( float i = 0.0; i <= 1.0; i += .1 )
    {
        vec3 pattern = smoothstep(.47,.53,texture(iChannel0,uv*.001).rgb);
        col = mix( col, i*pattern, SampleFuzz( uv*.02, i ) );
        uv -= .012;
    }
    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(0.5,0.5,1.),H(g*.1),.8)*5./e/8e3
    )
    {
        p=g*d;
      p.x+=iTime*0.02;
     p.xy*=col.xy;


        a=30.;
        p=mod(p-a,a*2.)-a;
        s=1.;
        for(int i=0;i++<8;){
            p=.3-abs(p);
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=1.7+sin(iTime*.01)*.01;
            p=abs(p)*e-
                vec3(
                    5.*3.,
                    120,
                    8.*5.
                 );
         }
         g+=e=length(p.yz)/s;
    }
}
